#!/usr/bin/env python3
"""Exercise current Bluetooth menu and event handlers against input/radio shims."""
from pathlib import Path
import tempfile, subprocess, os
ROOT=Path(__file__).resolve().parent.parent
SHIM='#include <cassert>\n#include <string>\n#include <vector>\n#include <array>\n#include <deque>\n#include <iostream>\n#include "BluetoothRetryPolicy.h"\nstruct String:std::string{using std::string::string;using std::string::operator=;void remove(size_t p){erase(p);}unsigned toInt(){return std::stoul(*this);}};\nnamespace Keyboard_Class {struct KeysState {bool ctrl=false,space=false,opt=false,del=false,enter=false,shift=false,alt=false,tab=false;unsigned modifiers=0;std::vector<char>word;void reset(){*this=KeysState{};}};}\nstruct Scan{void stop(){}};\nstruct Client{bool connected=true;int cancelled=0,disconnected=0;bool isConnected(){return connected;}void disconnect(){++disconnected;connected=false;}void cancelConnect(){++cancelled;}};\nstruct Device{struct Addr{std::string toString(){return "fake";}};std::string getName(){return "fake";}Addr getAddress(){return {};}};\nstruct NimBLEDevice{static Scan*getScan(){static Scan s;return &s;}static void injectConfirmPasskey(int,bool){}static void injectPassKey(int,unsigned){}};\nenum{BT_STATE_IDLE,BT_STATE_SCANNING,BT_STATE_PICKER};\nenum{MODE_MENU,MODE_EDITOR};enum{MENU_SETTINGS_BT,MENU_SETTINGS_WIFI,MENU_SETTINGS_DATETIME,MENU_SETTINGS_ABOUT,MENU_SETTINGS_PRINTER,MENU_SETTINGS_SYNC};\nint appMode=MODE_MENU,currentMenu=MENU_SETTINGS_BT,btSetupState=BT_STATE_IDLE,btMenuIndex=0,btSelectedDevice=0,btPairKind=0;\nString btPairDigits,btKeyboardName,btKeyboardAddress;int*btPairInfo=nullptr;Client*btKeyboardClient=nullptr;Device*btKeyboardAdvDevice=nullptr;std::vector<Device*>btScanDevices;\nbool btEnabledPreference=true,btConnectBusy=false,btInitDone=true,btWanted=false,btShutdownPending=false,btKeyboardConnected=true,btPowerOnAutoConnect=true,btAutoScan=false,btAutomaticAttempt=false,btReconnectDirect=false,needsRedraw=false;\nBluetoothRetryPolicy btRetryPolicy;\nbool btRepeatEligible=true,btKeyHeld=false,haveLastAction=true,keyHeld=true,savedAfterIdle=true;\nstd::array<bool,256>btHeld{};unsigned btRepeatUsage=44;unsigned long btKeyPressStartTime=0,btLastKeyActionTime=0,lastKeyPressTime=0;\nconstexpr unsigned KEY_REPEAT_DELAY_MS=500,KEY_REPEAT_RATE_MS=100;\nunsigned long now=1000;unsigned long millis(){return now;}\nint cycles=0,textInserted=0,radioOffCalls=0,saved=0;bool lastOffPersist=false;\nvoid cycleKeyboardLayout(){++cycles;}\n\nvoid btKeyboardDisconnect(){}void forgetBluetoothKeyboardConfig(){}void btStartConnect(){}void btKeyboardStartScan(){}void btEnableKeyboard(){}\nvoid saveBluetoothKeyboardConfigToSD(){++saved;}void showStatusMessage(const char*,int){}\nvoid openMenu(int id){currentMenu=id;}\nvoid btKeyboardPollConnection(){}void btProcessHidReports(){}\nvoid insertText(const char*){++textInserted;}\n#define STUB(name) void name(){}\nSTUB(journalUndo) STUB(journalRedo) STUB(journalFind) STUB(openMainMenu) STUB(backspaceChar) STUB(insertNewline) STUB(insertTab)\nSTUB(moveCursorUp) STUB(moveCursorDown) STUB(moveCursorLeft) STUB(moveCursorRight) STUB(deleteWordBackwards) STUB(deleteWordForwards)\nSTUB(moveCursorWordLeft) STUB(moveCursorWordRight) STUB(scrollPageUp) STUB(scrollPageDown) STUB(moveCursorHome) STUB(moveCursorEnd)\nSTUB(moveCursorDocHome) STUB(moveCursorDocEnd) STUB(deleteForwardChar) STUB(menuBack) STUB(menuSelect) STUB(menuMoveUp) STUB(menuMoveDown)\nvoid handleWiFiSetupKeys(const Keyboard_Class::KeysState&){}void handleDateTimeEditorKeys(const Keyboard_Class::KeysState&){}\nvoid handleAboutScreenKeys(const Keyboard_Class::KeysState&){}void handlePrinterSetupKeys(const Keyboard_Class::KeysState&){}\n'
QUEUE='\nstd::deque<BtInputEvent>events;\nBtInputEvent btRepeatEvent{};\nbool btQueuePushEvent(const BtInputEvent&e){events.push_back(e);return true;}\nbool btQueuePopEvent(BtInputEvent&e){if(events.empty())return false;e=events.front();events.pop_front();return true;}\n'
MAIN='\nint main(){\n Keyboard_Class::KeysState ks;ks.ctrl=ks.space=true;\n handleBluetoothKeyboardSetupKeys(ks);assert(cycles==1&&textInserted==0);\n ks.reset();ks.enter=true;btMenuIndex=3;\n handleBluetoothKeyboardSetupKeys(ks);assert(cycles==2&&textInserted==0);\n BtInputEvent e{};e.type=BT_EVENT_COMMAND;e.command=BT_CMD_LAYOUT;e.hidUsage=0x2c;e.modifiers=1;\n events.push_back(e);btHeld[btRepeatUsage]=true;btRepeatEligible=true;\n handleBluetoothInput();assert(cycles==3&&textInserted==0&&!btRepeatEligible);\n appMode=MODE_EDITOR;now+=2000;handleBtKeyRepeat();assert(events.empty());\n appMode=MODE_MENU;currentMenu=MENU_SETTINGS_BT;ks.reset();ks.enter=true;btMenuIndex=1;btConnectBusy=true;btWanted=true;Client client;btKeyboardClient=&client;btRetryPolicy.boot(true,true,true);assert(btRetryPolicy.takeAttempt());\n handleBluetoothKeyboardSetupKeys(ks);assert(!btEnabledPreference&&btShutdownPending&&!btWanted&&!btRetryPolicy.active()&&btRetryPolicy.attempts()==0);assert(client.cancelled==1&&client.disconnected==1);\n btMenuIndex=2;btConnectBusy=false;handleBluetoothKeyboardSetupKeys(ks);assert(!btPowerOnAutoConnect&&saved==2);\n std::cout<<"Built-in/BLE settings layout shortcuts, held BLE key suppression and busy manual-Off dispatch passed\\n";\n}\n'
src=(ROOT/'JournalBluetooth.inl').read_text()
ino=(ROOT/'Tiny_Journal.ino').read_text()
def function(name):
    start=src.index(name)
    if src[src.index(')',start)+1:].lstrip().startswith(';'):start=src.index(name,start+1)
    brace=src.index('{',start);depth=1;p=brace+1
    while depth:
        depth+=(src[p]=='{')-(src[p]=='}');p+=1
    return src[start:p]
events=ino[ino.index('enum BtInputEventType'):ino.index('const int BT_INPUT_EVENT_QUEUE_SIZE')]
code=SHIM+events+QUEUE+'\n'.join(function(name) for name in ['void btRequestPowerOff(', 'bool btEventToKeys(', 'void handleBluetoothKeyboardSetupKeys(', 'void handleBtKeyRepeat(', 'void handleBluetoothInput()'])+MAIN
with tempfile.TemporaryDirectory(prefix='journal-bt-shortcuts-') as directory:
    cpp=Path(directory)/'test.cpp';binary=Path(directory)/'test';cpp.write_text(code)
    subprocess.run([os.environ.get('CXX','c++'),'-std=c++17','-fsanitize=address,undefined','-I'+str(ROOT),str(cpp),'-o',str(binary)],check=True)
    subprocess.run([str(binary)],check=True)
